     1→/**
     2→ * Setup status utilities
     3→ *
     4→ * Extracted from cli/commands/setup.ts to avoid CLI module dependency for doctor.ts.
     5→ * Provides setup status information without output formatting.
     6→ *
     7→ * AC: @doctor-command ac-setup-agent-hooks, ac-setup-skills-agents-md, ac-partial-init, ac-staleness-unknown
     8→ */
     9→
    10→import * as fs from "node:fs/promises";
    11→import * as path from "node:path";
    12→
    13→/**
    14→ * Detected agent type
    15→ */
    16→export type AgentType = "claude-code" | "cursor" | "windsurf" | "unknown";
    17→
    18→/**
    19→ * Setup status information
    20→ * AC: @enhanced-setup ac-7, ac-8 - status reporting
    21→ */
    22→export interface SetupStatus {
    23→  agent: {
    24→    detected: AgentType;
    25→    confidence: "high" | "medium" | "low";
    26→  };
    27→  hooks: {
    28→    promptCheck: boolean;
    29→    stop: boolean;
    30→    preToolUse: boolean;
    31→    guardsPresent: string[];
    32→  };
    33→  skills: {
    34→    total: number;
    35→    rendered: number;
    36→    drifted: number;
    37→  };
    38→  agentsMd: {
    39→    exists: boolean;
    40→    status: "current" | "stale" | "missing" | "unknown";
    41→    generatedAt?: string;
    42→  };
    43→  seeding: {
    44→    permissionsSeeded: boolean;
    45→    memorySeeded: boolean;
    46→    memoryPath?: string;
    47→  };
    48→  /** Error message if status check failed */
    49→  error?: string;
    50→}
    51→
    52→/**
    53→ * Guard scripts that can be installed
    54→ */
    55→const GUARD_SCRIPTS: Record<string, boolean> = {
    56→  "bash-guard.mjs": true,
    57→  "write-guard.mjs": true,
    58→  "edit-guard.mjs": true,
    59→};
    60→
    61→/**
    62→ * Detect the agent type in use.
    63→ */
    64→export async function detectAgent(): Promise<{
    65→  type: AgentType;
    66→  confidence: "high" | "medium" | "low";
    67→}> {
    68→  // Check environment variables for agent hints
    69→  const envHints = {
    70→    CLAUDE_CODE: "claude-code",
    71→    CURSOR_TRACE_ID: "cursor",
    72→    WINDSURF_SESSION: "windsurf",
    73→  } as const;
    74→
    75→  for (const [envVar, agent] of Object.entries(envHints)) {
    76→    if (process.env[envVar]) {
    77→      return { type: agent as AgentType, confidence: "high" };
    78→    }
    79→  }
    80→
    81→  // Check for Claude Code by looking for .claude directory
    82→  // This is a medium confidence indicator
    83→  if (process.env.HOME) {
    84→    // Global Claude Code config at ~/.claude
    85→    const globalClaudeDir = path.join(process.env.HOME, ".claude");
    86→    try {
    87→      const stats = await fs.stat(globalClaudeDir);
    88→      if (stats.isDirectory()) {
    89→        return { type: "claude-code", confidence: "medium" };
    90→      }
    91→    } catch {
    92→      // Directory doesn't exist
    93→    }
    94→  }
    95→
    96→  return { type: "unknown", confidence: "low" };
    97→}
    98→
    99→/**
   100→ * Debug logging helper
   101→ */
   102→function debugLog(message: string, _error?: unknown): void {
   103→  if (process.env.KSPEC_DEBUG === "1") {
   104→    console.error(`[DEBUG] ${message}`);
   105→  }
   106→}
   107→
   108→/**
   109→ * Get the current setup status for a project.
   110→ *
   111→ * AC: @doctor-command ac-setup-agent-hooks — checks hooks status
   112→ * AC: @doctor-command ac-setup-skills-agents-md — checks skills and agents.md
   113→ * AC: @doctor-command ac-partial-init — handles missing setup artifacts
   114→ * AC: @doctor-command ac-staleness-unknown — returns "unknown" when staleness cannot be determined
   115→ *
   116→ * @param projectDir Project root directory
   117→ */
   118→export async function getSetupStatus(projectDir: string): Promise<SetupStatus> {
   119→  const detected = await detectAgent();
   120→  const configPath = path.join(projectDir, ".claude", "settings.json");
   121→  const hooksDir = path.join(projectDir, ".claude", "hooks");
   122→  const agentsMdPath = path.join(projectDir, "kspec-agents.md");
   123→  const hashPath = path.join(projectDir, ".kspec", ".kspec-agents-hash");
   124→  const skillsDir = path.join(projectDir, ".claude", "skills");
   125→
   126→  // Check hooks
   127→  const hooks = {
   128→    promptCheck: false,
   129→    stop: false,
   130→    preToolUse: false,
   131→    guardsPresent: [] as string[],
   132→  };
   133→
   134→  try {
   135→    const configContent = await fs.readFile(configPath, "utf-8");
   136→    const config = JSON.parse(configContent);
   137→    const hooksConfig = config.hooks || {};
   138→
   139→    // Check UserPromptSubmit
   140→    const promptHooks = hooksConfig.UserPromptSubmit as
   141→      | Array<{ hooks?: Array<{ command?: string }> }>
   142→      | undefined;
   143→    hooks.promptCheck =
   144→      promptHooks?.some((entry) =>
   145→        entry.hooks?.some((h) => h.command?.includes("prompt-check"))
   146→      ) ?? false;
   147→
   148→    // Check Stop
   149→    const stopHooks = hooksConfig.Stop as
   150→      | Array<{ hooks?: Array<{ command?: string }> }>
   151→      | undefined;
   152→    hooks.stop =
   153→      stopHooks?.some((entry) =>
   154→        entry.hooks?.some((h) => h.command?.includes("checkpoint"))
   155→      ) ?? false;
   156→
   157→    // Check PreToolUse
   158→    const preToolUseHooks = hooksConfig.PreToolUse as
   159→      | Array<{ hooks?: Array<{ command?: string }> }>
   160→      | undefined;
   161→    hooks.preToolUse =
   162→      preToolUseHooks?.some((entry) =>
   163→        entry.hooks?.some((h) => h.command?.includes(".claude/hooks/"))
   164→      ) ?? false;
   165→  } catch (err) {
   166→    debugLog("Failed to read hooks config for status", err);
   167→  }
   168→
   169→  // Check guard scripts
   170→  try {
   171→    const guardFiles = await fs.readdir(hooksDir);
   172→    for (const name of Object.keys(GUARD_SCRIPTS)) {
   173→      if (guardFiles.includes(name)) {
   174→        hooks.guardsPresent.push(name);
   175→      }
   176→    }
   177→  } catch (err) {
   178→    debugLog("Hooks dir doesn't exist", err);
   179→  }
   180→
   181→  // Check skills
   182→  const skills = {
   183→    total: 0,
   184→    rendered: 0,
   185→    drifted: 0,
   186→  };
   187→
   188→  try {
   189→    const skillDirs = await fs.readdir(skillsDir, { withFileTypes: true });
   190→    for (const dir of skillDirs) {
   191→      if (dir.isDirectory()) {
   192→        const skillMdPath = path.join(skillsDir, dir.name, "SKILL.md");
   193→        try {
   194→          const content = await fs.readFile(skillMdPath, "utf-8");
   195→          if (content.includes("<!-- kspec-managed -->")) {
   196→            skills.total++;
   197→            skills.rendered++;
   198→            // TODO: check drift status
   199→          }
   200→        } catch (err) {
   201→          debugLog(`SKILL.md doesn't exist in ${dir.name}`, err);
   202→        }
   203→      }
   204→    }
   205→  } catch (err) {
   206→    debugLog("Skills dir doesn't exist", err);
   207→  }
   208→
   209→  // Check agents.md
   210→  const agentsMd: SetupStatus["agentsMd"] = {
   211→    exists: false,
   212→    status: "missing",
   213→  };
   214→
   215→  try {
   216→    await fs.access(agentsMdPath);
   217→    agentsMd.exists = true;
   218→
   219→    try {
   220→      const hashContent = await fs.readFile(hashPath, "utf-8");
   221→      const hashData = JSON.parse(hashContent);
   222→      agentsMd.generatedAt = hashData.generatedAt;
   223→
   224→      // AC: @doctor-command ac-staleness-unknown
   225→      // Compare stored hash against current meta to detect staleness
   226→      try {
   227→        const { initContext, loadMetaContext } = await import("./index.js");
   228→        // Dynamic import agents.js from CLI commands
   229→        const { computeMetaHash, loadTemplateSections, getPackageRoot } = await import(
   230→          "../cli/commands/agents.js"
   231→        );
   232→        const ctx = await initContext();
   233→        if (ctx.manifestPath) {
   234→          const metaCtx = await loadMetaContext(ctx);
   235→          let templateSections: string[] = [];
   236→          try {
   237→            templateSections = await loadTemplateSections(getPackageRoot());
   238→          } catch (err) {
   239→            debugLog("Templates not available for staleness check", err);
   240→          }
   241→          const currentHash = computeMetaHash(
   242→            metaCtx.skills,
   243→            metaCtx.conventions,
   244→            metaCtx.workflows,
   245→            templateSections
   246→          );
   247→          agentsMd.status = hashData.metaHash === currentHash ? "current" : "stale";
   248→        } else {
   249→          // AC: @doctor-command ac-staleness-unknown — no manifest means we can't check
   250→          agentsMd.status = "unknown";
   251→        }
   252→      } catch (err) {
   253→        // AC: @doctor-command ac-staleness-unknown — hash computation failed
   254→        debugLog("Could not compute meta hash for staleness check", err);
   255→        agentsMd.status = "unknown";
   256→      }
   257→    } catch (err) {
   258→      debugLog("Hash file missing or invalid, marking stale", err);
   259→      agentsMd.status = "stale";
   260→    }
   261→  } catch (err) {
   262→    debugLog("kspec-agents.md doesn't exist", err);
   263→  }
   264→
   265→  // Check seeding state
   266→  const seeding: SetupStatus["seeding"] = {
   267→    permissionsSeeded: false,
   268→    memorySeeded: false,
   269→  };
   270→
   271→  try {
   272→    const configContent = await fs.readFile(
   273→      path.join(projectDir, ".claude", "settings.json"),
   274→      "utf-8"
   275→    );
   276→    const config = JSON.parse(configContent);
   277→    seeding.permissionsSeeded = !!config.permissions;
   278→  } catch (err) {
   279→    debugLog("Could not check permissions seeding state", err);
   280→  }
   281→
   282→  if (detected.type === "claude-code") {
   283→    try {
   284→      const { claudeCodeMemoryWriter } = await import(
   285→        "../cli/commands/setup-seeding.js"
   286→      );
   287→      const memoryExists = await claudeCodeMemoryWriter.exists(projectDir);
   288→      seeding.memorySeeded = memoryExists;
   289→      if (memoryExists) {
   290→        seeding.memoryPath = claudeCodeMemoryWriter.getMemoryPath(projectDir);
   291→      }
   292→    } catch (err) {
   293→      debugLog("Could not check memory seeding state", err);
   294→    }
   295→  }
   296→
   297→  return {
   298→    agent: {
   299→      detected: detected.type,
   300→      confidence: detected.confidence,
   301→    },
   302→    hooks,
   303→    skills,
   304→    agentsMd,
   305→    seeding,
   306→  };
   307→}
